/*
 * A015846  Inverse of 1837th cyclotomic polynomial.
 * https://oeis.org/A015846
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, easy, changed
 * Formula:   a(n) = coefficient of x^n in the series expansion of 1/Φ₁₈₃₇(x)
 * Range:     i8 n <= 2000, i16 n <= 2000, i32 n <= 2000, i64 n <= 2000,
 *            i128 n <= 2000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is periodic with period 1837. The coefficients are generated by  */
/* the recurrence derived from the cyclotomic polynomial Φ₁₈₃₇(x).                */
#include <stddef.h>
#include <stdbool.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* Local constants */
    enum { N = 1837, DEG = 1660, DIV_DEG = 10, NUM_DEG = 1670, DIV_POLY_DEG = 10 };

    /* Static storage for coefficients of Φ₁₈₃₇(x) and the sequence values */
    static bool initialized = false;
    static seq_t phi_coeff[DEG + 1];
    static seq_t seq_vals[N];
    if (!initialized) {
        /* Step 1: Compute Φ₁₈₃₇(x) = (∑_{k=0}^{10} x^{167k}) / (1 + x + … + x¹⁰) */
        /* Prepare numerator polynomial N(x) of degree 1670 */
        seq_t num[NUM_DEG + 1] = {0};
        for (int k = 0; k <= 10; ++k) num[167 * k] = (seq_t)1;
        /* Work array for division */
        seq_t work[NUM_DEG + 1];
        for (int i = 0; i <= NUM_DEG; ++i) work[i] = num[i];
        /* Denominator polynomial D(x) = 1 + x + … + x¹⁰, leading coefficient is 1 */
        const seq_t one = (seq_t)1;
        /* Resulting Φ coefficients */
        for (int i = 0; i <= DEG; ++i) phi_coeff[i] = 0;
        /* Long division */
        for (int i = NUM_DEG; i >= DIV_DEG; --i) {
            seq_t coeff = work[i];
            if (coeff) {
                int shift = i - DIV_DEG;
                phi_coeff[shift] = coeff;      /* since leading coeff of D is 1 */
                for (int j = 0; j <= DIV_POLY_DEG; ++j) {
                    work[shift + j] -= coeff * one;   /* D[j] == 1 for all j */
                }
            }
        }
        /* Step 2: Generate the sequence via the recurrence:
           a[n] = -∑_{k=1}^{DEG} phi_coeff[k] * a[n-k]   for n ≥ 1,  a[0] = 1
        */
        seq_vals[0] = one;
        for (idx_t i = 1; i < N; ++i) {
            seq_t sum = 0;
            int maxk = (i <= DEG) ? (int)i : DEG;
            for (int k = 1; k <= maxk; ++k) {
                sum += phi_coeff[k] * seq_vals[i - k];
            }
            seq_vals[i] = -sum;
        }
        initialized = true;
    }

    /* Return the periodic value */
    idx_t m = n % (idx_t)N;
    return seq_vals[(size_t)m];
}
